CREATE DATABASE IF NOT EXISTS pustakanusa CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE pustakanusa;

CREATE TABLE categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, description TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE members (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, member_no VARCHAR(30) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, email VARCHAR(120) NOT NULL UNIQUE, phone VARCHAR(30), address TEXT, password_hash VARCHAR(255) NOT NULL, registration_status ENUM('menunggu','disetujui','ditolak') NOT NULL DEFAULT 'disetujui', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE staff (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, username VARCHAR(60) NOT NULL UNIQUE, email VARCHAR(120) NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('superadmin','petugas') NOT NULL DEFAULT 'petugas', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE books (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, category_id BIGINT UNSIGNED NOT NULL, title VARCHAR(255) NOT NULL, author VARCHAR(180) NOT NULL, publisher VARCHAR(180), published_year SMALLINT, pages INT, language VARCHAR(60) DEFAULT 'Indonesia', isbn VARCHAR(32), price DECIMAL(12,2) NOT NULL DEFAULT 0, stock INT NOT NULL DEFAULT 0, synopsis TEXT, cover_image LONGTEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_books_category FOREIGN KEY (category_id) REFERENCES categories(id));
CREATE TABLE loans (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, member_id BIGINT UNSIGNED NOT NULL, staff_id BIGINT UNSIGNED NULL, loan_date DATE NOT NULL, due_date DATE NOT NULL, returned_date DATE NULL, status ENUM('menunggu','siap_diambil','dipinjam','dikembalikan','terlambat','dibatalkan') NOT NULL DEFAULT 'menunggu', pickup_location VARCHAR(180), pickup_date DATE NULL, pickup_time VARCHAR(50), fine_total DECIMAL(12,2) NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_loans_member FOREIGN KEY (member_id) REFERENCES members(id), CONSTRAINT fk_loans_staff FOREIGN KEY (staff_id) REFERENCES staff(id));
CREATE TABLE loan_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, loan_id BIGINT UNSIGNED NOT NULL, book_id BIGINT UNSIGNED NOT NULL, price_at_loan DECIMAL(12,2) NOT NULL, fine DECIMAL(12,2) NOT NULL DEFAULT 0, CONSTRAINT fk_items_loan FOREIGN KEY (loan_id) REFERENCES loans(id) ON DELETE CASCADE, CONSTRAINT fk_items_book FOREIGN KEY (book_id) REFERENCES books(id));
CREATE TABLE complaints (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, member_id BIGINT UNSIGNED NOT NULL, book_id BIGINT UNSIGNED NULL, type VARCHAR(100) NOT NULL, description TEXT NOT NULL, attachment VARCHAR(255), status ENUM('baru','diproses','selesai','ditolak') NOT NULL DEFAULT 'baru', fine_amount DECIMAL(12,2) NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_complaint_member FOREIGN KEY (member_id) REFERENCES members(id), CONSTRAINT fk_complaint_book FOREIGN KEY (book_id) REFERENCES books(id));
CREATE TABLE complaint_attachments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, complaint_id BIGINT UNSIGNED NOT NULL, file_name VARCHAR(180) NOT NULL, mime_type VARCHAR(40) NOT NULL, image_data MEDIUMTEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_complaint_attachments_complaint (complaint_id), CONSTRAINT fk_complaint_attachment FOREIGN KEY (complaint_id) REFERENCES complaints(id) ON DELETE CASCADE);
CREATE TABLE notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, member_id BIGINT UNSIGNED NOT NULL, message VARCHAR(255) NOT NULL, type VARCHAR(40) NOT NULL DEFAULT 'info', is_read BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_notification_member FOREIGN KEY (member_id) REFERENCES members(id) ON DELETE CASCADE);
CREATE TABLE staff_notification_reads (staff_id BIGINT UNSIGNED NOT NULL, notification_key VARCHAR(80) NOT NULL, read_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (staff_id,notification_key), CONSTRAINT fk_staff_notification_read FOREIGN KEY (staff_id) REFERENCES staff(id) ON DELETE CASCADE);
CREATE TABLE fine_payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, member_id BIGINT UNSIGNED NOT NULL, source_type ENUM('loan','complaint') NOT NULL, source_id BIGINT UNSIGNED NOT NULL, amount DECIMAL(12,2) NOT NULL, due_date DATE NULL, method ENUM('qris','va_bca','gopay','dana','ovo') NULL, status ENUM('menunggu','dibayar') NOT NULL DEFAULT 'menunggu', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, paid_at TIMESTAMP NULL, UNIQUE KEY unique_fine_payment (source_type,source_id), CONSTRAINT fk_payment_member FOREIGN KEY (member_id) REFERENCES members(id) ON DELETE CASCADE);

